suppressPackageStartupMessages({
  library(Seurat)
  library(SeuratObject)
  library(dplyr)
  library(tibble)
  library(readr)
})

cat("============================================================\n")
cat("PIPELINE_V2 — 21D COMMUNICATION RESOURCE PREFLIGHT\\n")

# Canonical frozen communication atlas generated by 21B
OBJ_IN <- paste0(
  "PIPELINE_V2/objects/frozen/",
  "global_atlas_v2_21B_communication_frozen.rds"
)
cat("============================================================\n")

# ============================================================
# 1. Paths
# ============================================================

ROOT <- file.path(
  "PIPELINE_V2",
  "results",
  "disease_biology",
  "21_CELL_CELL_COMMUNICATION"
)

IN21B <- file.path(
  ROOT,
  "21B_FROZEN_COMMUNICATION_ATLAS"
)

IN21C <- file.path(
  ROOT,
  "21C_COMMUNICATION_DESIGN"
)

OUT <- file.path(
  ROOT,
  "21D_RESOURCE_PREFLIGHT"
)

dir.create(
  OUT,
  recursive=TRUE,
  showWarnings=FALSE
)

# ============================================================
# 2. Locate frozen 21B communication object
# ============================================================

cat("\nSTEP 1/7 — locating frozen 21B communication atlas\n")

COMM_RDS <- file.path(
  "PIPELINE_V2",
  "objects",
  "frozen",
  "global_atlas_v2_21B_communication_frozen.rds"
)

if (!file.exists(COMM_RDS)) {
  stop(
    "Frozen 21B communication atlas not found: ",
    COMM_RDS
  )
}

cat("Frozen communication atlas:\n")
cat(COMM_RDS, "\n")

obj <- readRDS(COMM_RDS)

cat("Cells   :", ncol(obj), "\n")
cat("Features:", nrow(obj), "\n")

stopifnot(
  ncol(obj) == 82893,
  nrow(obj) == 23412
)

cat("\nSTEP 2/7 — auditing frozen communication metadata\n")

md <- obj[[]]

required <- c(
  "patient_id",
  "disease",
  "batch",
  "communication_L1",
  "communication_L2",
  "communication_identity",
  "communication_annotation_level"
)

metadata_check <- tibble(
  field=required,
  present=required %in% names(md)
)

print(tibble::as_tibble(metadata_check), n=Inf, width=Inf)

stopifnot(all(metadata_check$present))

cat("\nCommunication identities:",
    n_distinct(md$communication_identity),"\n")

cat("\nDisease counts:\n")
print(
  tibble::as_tibble(
    md %>%
      count(disease)
  ),
  n=Inf,
  width=Inf
)

# ============================================================
# 4. RNA layers
# ============================================================

cat("\nSTEP 3/7 — auditing expression layers\n")

DefaultAssay(obj) <- "RNA"

layers <- Layers(obj[["RNA"]])

cat("RNA layers:",
    paste(layers,collapse="; "),
    "\n")

stopifnot(
  "counts" %in% layers,
  "data" %in% layers
)

# ============================================================
# 5. Communication package environment
# ============================================================

cat("\nSTEP 4/7 — communication package environment\n")

pkgs <- c(
  "CellChat",
  "LIANA",
  "liana",
  "NicheNetR",
  "nichenetr",
  "OmnipathR",
  "OmnipathR",
  "decoupleR",
  "SingleCellExperiment"
)

pkg_inventory <- tibble(
  package=pkgs
) %>%
  distinct() %>%
  rowwise() %>%
  mutate(
    installed=
      requireNamespace(
        package,
        quietly=TRUE
      ),
    version=
      if (installed)
        as.character(
          packageVersion(package)
        )
      else
        NA_character_
  ) %>%
  ungroup()

print(tibble::as_tibble(pkg_inventory), n=Inf, width=Inf)

write_csv(
  pkg_inventory,
  file.path(
    OUT,
    "21D_package_inventory.csv"
  )
)

# ============================================================
# 6. Search for existing LR resources
# ============================================================

cat("\nSTEP 5/7 — searching local ligand-receptor resources\n")

search_roots <- c(
  "PIPELINE_V2",
  "01_RAW_DATA",
  "02_PROCESSED_DATA",
  "08_REPRODUCIBILITY"
)

search_roots <- search_roots[
  dir.exists(search_roots)
]

files <- unlist(
  lapply(
    search_roots,
    function(d) {
      list.files(
        d,
        recursive=TRUE,
        full.names=TRUE
      )
    }
  ),
  use.names=FALSE
)

lr_candidates <- files[
  grepl(
    paste0(
      "cellchat|cellphonedb|cell_phone|",
      "ligand|receptor|omnipath|",
      "nichenet|liana"
    ),
    basename(files),
    ignore.case=TRUE
  )
]

lr_inventory <- tibble(
  file=sort(unique(lr_candidates))
)

cat(
  "Local LR/resource candidates:",
  nrow(lr_inventory),
  "\n"
)

if (nrow(lr_inventory)) {
  print(
    tibble::as_tibble(lr_inventory),
    n=Inf,
    width=Inf
  )
}

write_csv(
  lr_inventory,
  file.path(
    OUT,
    "21D_local_LR_resource_inventory.csv"
  )
)

# ============================================================
# 7. Frozen identity support
# ============================================================

cat("\nSTEP 6/7 — identity support for communication inference\n")

identity_support <- md %>%
  count(
    communication_identity,
    disease,
    patient_id,
    name="n_cells"
  ) %>%
  group_by(
    communication_identity,
    disease
  ) %>%
  summarise(
    n_patients=n_distinct(patient_id),
    total_cells=sum(n_cells),
    median_cells=median(n_cells),
    min_cells=min(n_cells),
    n_patients_ge20=sum(n_cells >= 20),
    n_patients_ge50=sum(n_cells >= 50),
    .groups="drop"
  )

write_csv(
  identity_support,
  file.path(
    OUT,
    "21D_identity_patient_support.csv"
  )
)

print(
  tibble::as_tibble(identity_support),
  n=Inf,
  width=Inf
)

# ============================================================
# 8. Formal checks
# ============================================================

cat("\nSTEP 7/7 — formal checks\n")

checks <- tibble(
  check=c(
    "21B_object_found",
    "global_cells_82893",
    "communication_identity_present",
    "patient_metadata_present",
    "disease_metadata_present",
    "batch_metadata_present",
    "RNA_counts_present",
    "RNA_data_present",
    "package_inventory_generated",
    "LR_resource_inventory_generated",
    "identity_support_generated",
    "no_package_installed",
    "no_LR_resource_selected",
    "no_communication_inference",
    "no_DE_refit",
    "no_pathway_refit",
    "annotation_unchanged",
    "source_object_not_overwritten"
  ),
  pass=c(
    file.exists(OBJ_IN),
    ncol(obj) == 82893,
    "communication_identity" %in% names(md),
    "patient_id" %in% names(md),
    "disease" %in% names(md),
    "batch" %in% names(md),
    "counts" %in% layers,
    "data" %in% layers,
    file.exists(
      file.path(
        OUT,
        "21D_package_inventory.csv"
      )
    ),
    file.exists(
      file.path(
        OUT,
        "21D_local_LR_resource_inventory.csv"
      )
    ),
    file.exists(
      file.path(
        OUT,
        "21D_identity_patient_support.csv"
      )
    ),
    TRUE,
    TRUE,
    TRUE,
    TRUE,
    TRUE,
    TRUE,
    TRUE
  )
)

print(tibble::as_tibble(checks), n=Inf, width=Inf)

stopifnot(all(checks$pass))

write_csv(
  checks,
  file.path(
    OUT,
    "21D_formal_checks.csv"
  )
)

audit <- c(
  "PIPELINE_V2 — 21D communication resource preflight",
  "",
  paste0("Date: ",Sys.Date()),
  "",
  paste0("Frozen communication atlas: ",OBJ_IN),
  "",
  "Purpose:",
  paste(
    "Audit communication software, ligand-receptor resources,",
    "expression layers and patient support before selecting",
    "the communication-inference framework."
  ),
  "",
  "No package installed.",
  "No ligand-receptor resource selected.",
  "No communication inference performed.",
  "No differential-expression refit.",
  "No pathway refit.",
  "No annotation modified."
)

writeLines(
  audit,
  file.path(
    OUT,
    "21D_audit.txt"
  )
)

cat("\n============================================================\n")
cat("21D PREFLIGHT COMPLETE\n")
cat("============================================================\n")
cat("Communication software environment audited\n")
cat("Local ligand-receptor resources inventoried\n")
cat("Patient support audited\n")
cat("No resource selected yet\n")
cat("No communication inference performed\n")
cat("PASS\n")
